from functools import wraps
import time

# Decorador básico
def mayusculas(funcion):
    @wraps(funcion)
    def wrapper(*args, **kwargs):
        resultado = funcion(*args, **kwargs)
        return resultado.upper()
    return wrapper

@mayusculas
def saludar(nombre):
    return f"hola, {nombre}"

print(saludar("mundo"))   # HOLA, MUNDO

# Decorador para medir tiempo de ejecución
def medir_tiempo(funcion):
    @wraps(funcion)
    def wrapper(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = funcion(*args, **kwargs)
        fin = time.perf_counter()
        print(f"{funcion.__name__} tardó {fin - inicio:.4f}s")
        return resultado
    return wrapper

@medir_tiempo
def suma_lenta(n):
    return sum(range(n))

total = suma_lenta(1_000_000)
print(f"Suma: {total}")

# Decorador con argumentos
def repetir(veces):
    def decorador(funcion):
        @wraps(funcion)
        def wrapper(*args, **kwargs):
            for _ in range(veces):
                resultado = funcion(*args, **kwargs)
            return resultado
        return wrapper
    return decorador

@repetir(3)
def decir(mensaje):
    print(mensaje)

decir("¡Hola!")   # imprime 3 veces

# Apilar decoradores
@medir_tiempo
@mayusculas
def obtener_saludo(nombre):
    return f"buenos días, {nombre}"

print(obtener_saludo("Ana"))

class Animal:
    def __init__(self, nombre, edad):
        self.nombre = nombre
        self.edad   = edad

    def respirar(self):
        print(f"{self.nombre} respira")

    def sonido(self):
        raise NotImplementedError("Cada animal debe implementar su sonido")

    def __str__(self):
        return f"{type(self).__name__}: {self.nombre} ({self.edad} años)"


class Perro(Animal):
    def __init__(self, nombre, edad, raza):
        super().__init__(nombre, edad)   # inicializa nombre y edad
        self.raza = raza

    def sonido(self):
        return "¡Guau guau!"

    def buscar(self, objeto):
        print(f"{self.nombre} va a buscar el {objeto}")


class Gato(Animal):
    def __init__(self, nombre, edad, indoor=True):
        super().__init__(nombre, edad)
        self.indoor = indoor

    def sonido(self):
        return "¡Miau!"

    def ronronear(self):
        print(f"{self.nombre} ronronea...")


class PajaroCantor(Animal):
    def sonido(self):
        return "¡Pío pío!"

    def cantar(self):
        print(f"{self.nombre} canta una melodía")


# Polimorfismo en acción
animales = [
    Perro("Rex", 3, "Labrador"),
    Gato("Luna", 5),
    PajaroCantor("Pío", 2),
    Perro("Toby", 7, "Beagle"),
]

for animal in animales:
    print(f"{animal.nombre}: {animal.sonido()}")

# isinstance
print(isinstance(animales[0], Perro))   # True
print(isinstance(animales[0], Animal))  # True
print(isinstance(animales[1], Perro))   # False

# issubclass
print(issubclass(Perro, Animal))        # True
